@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Nunito:wght@500;600;700;800;900&family=Press+Start+2P&display=swap');
:root{--ink:#193955;--blue:#2269b4;--red:#f05142;--cream:#fffaf0;--yellow:#ffcf55}*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:'Nunito',sans-serif;color:var(--ink)}body{min-height:100vh;background:#f7f2e7;background-image:radial-gradient(#d8d0bc 0.75px,transparent .75px);background-size:18px 18px;display:flex;justify-content:center;align-items:center;padding:24px}.game-shell{width:min(1120px,100%)}.topbar{height:48px;display:flex;align-items:center;justify-content:space-between;margin:0 8px 13px}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:#1b4162;font-size:13px;font-weight:900;letter-spacing:1.55px}.brand-mark{width:30px;height:30px;display:grid;place-items:center;background:var(--red);border-radius:8px;color:white;font-family:'Press Start 2P';font-size:13px;box-shadow:0 3px 0 #bd4436}.brand-light{color:#e55345}.top-note,.sound-button{font-family:'DM Mono',monospace;font-size:10px;letter-spacing:1.1px}.top-note{color:#74899a}.live-dot{display:inline-block;width:7px;height:7px;background:#68bd81;border-radius:50%;margin-right:7px;box-shadow:0 0 0 3px #68bd8120}.divider{padding:0 7px;color:#c2b9a8}.sound-button{border:1px solid #dcd5c6;background:#fffaf2;border-radius:8px;padding:8px 10px;color:#5a7283;cursor:pointer}.sound-button span{font-size:9px}.game-card{padding:12px;background:#fffdf7;border:1px solid #e8dfce;border-radius:14px;box-shadow:0 8px 0 #e4dac7,0 16px 38px #415b6e1a}.game-stage{width:100%;aspect-ratio:16/9;position:relative;overflow:hidden;border-radius:7px;background:#87d9f4;isolation:isolate}.game-stage canvas{width:100%;height:100%;display:block;image-rendering:pixelated}.hud{position:absolute;inset:17px 21px auto;display:flex;align-items:flex-start;gap:28px;color:white;text-shadow:0 2px 3px #345d8180;pointer-events:none;z-index:2}.hud-stat{display:flex;flex-direction:column;gap:4px;min-width:60px}.hud-label{font-family:'DM Mono',monospace;font-weight:500;letter-spacing:1.4px;font-size:9px;opacity:.82}.hud-stat strong{font-family:'Press Start 2P',monospace;font-size:12px;line-height:1.5}.coins-stat{flex-direction:row;align-items:center;gap:7px;margin-top:12px}.coins-stat strong{font-size:10px}.coin-icon{color:#ffd340;font-size:18px;text-shadow:0 2px #ad7922}.lives-stat{margin-left:auto;text-align:right}.lives-stat strong{font-family:'Nunito',sans-serif;font-size:17px;letter-spacing:2px;color:#ff7061}.time-stat{text-align:right}.world-progress{height:4px;position:absolute;bottom:0;left:0;right:0;z-index:3;background:#254c5c22}.world-progress span{display:block;width:0;height:100%;background:#ffcf55;transition:width .15s}.screen-overlay{position:absolute;inset:0;z-index:4;display:flex;align-items:center;justify-content:center;background:linear-gradient(90deg,#173e646e,#174b7260);transition:opacity .25s,visibility .25s}.screen-overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.overlay-card{margin-top:22px;text-align:center;padding:28px 30px 21px;background:#fffaf0ee;border:2px solid #fff;border-radius:12px;box-shadow:0 6px 0 #294f6691;min-width:min(440px,90%)}.mini-kicker{font-family:'DM Mono',monospace;font-size:9px;letter-spacing:1.1px;color:#75909c}.mini-kicker span{color:#f3b936;padding:0 5px}.overlay-card h1{font-family:'Press Start 2P',monospace;color:#e64b3c;font-size:25px;line-height:1.55;margin:13px 0 9px;text-shadow:2px 3px 0 #f7ce59}.overlay-card h1 span{font-size:15px}.overlay-card h1 em{font-size:16px;letter-spacing:-.7px;color:#286eaa;font-style:normal;text-shadow:1px 2px 0 #aad9ec}.overlay-copy{font-size:13px;line-height:1.55;color:#668092;margin:8px 0 17px;font-weight:700}.play-button{background:#f05443;border:0;border-radius:7px;padding:13px 22px;color:white;font-family:'Nunito',sans-serif;font-size:12px;font-weight:900;letter-spacing:1.15px;box-shadow:0 4px 0 #bd4035;cursor:pointer;transition:transform .12s,box-shadow .12s}.play-button:hover{transform:translateY(-2px);box-shadow:0 6px 0 #bd4035}.play-button:active{transform:translateY(2px);box-shadow:0 2px 0 #bd4035}.play-button span{font-size:10px;padding-right:6px}.control-hint{margin-top:16px;display:flex;justify-content:center;align-items:center;gap:5px;font:9px 'DM Mono',monospace;letter-spacing:.7px;color:#79909b}kbd{font:9px 'DM Mono',monospace;background:#fff;border:1px solid #d8d5ca;border-radius:3px;padding:3px 5px;color:#637c89;box-shadow:0 1px 0 #d9d4c8}.control-hint i{padding:0 4px;font-style:normal}.game-footer{height:46px;display:flex;justify-content:space-between;align-items:center;padding:0 6px}.footer-tip{display:flex;align-items:center;gap:8px;color:#82939c;font-size:11px}.footer-tip b{font-family:'DM Mono',monospace;color:#d09d37;font-size:9px;letter-spacing:1px}.tip-icon{font-size:18px;color:#f3bd46}.footer-controls{display:flex;gap:18px;font:9px 'DM Mono',monospace;color:#8495a0;letter-spacing:.5px}.footer-controls span{display:flex;align-items:center;gap:4px}.footer-controls kbd{font-size:8px;padding:3px 4px}.page-foot{display:flex;justify-content:space-between;margin:22px 9px 0;font:9px 'DM Mono',monospace;letter-spacing:1.2px;color:#9aa8a6}.page-foot i{font-style:normal;color:#d19d38}.touch-controls{display:none}.toast{position:absolute;left:50%;top:23%;transform:translate(-50%,-10px);padding:9px 16px;border-radius:6px;background:#fff9e9;color:#b87929;font:10px 'DM Mono',monospace;letter-spacing:1px;opacity:0;transition:.2s;z-index:3;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:700px){body{padding:10px 8px 14px;align-items:flex-start}.topbar{height:34px;margin:0 2px 8px}.brand{font-size:10px;gap:7px}.brand-mark{width:25px;height:25px;font-size:10px}.top-note{font-size:8px;letter-spacing:.4px}.sound-button{padding:6px 7px;font-size:9px}.sound-button span{display:none}.game-card{padding:6px;border-radius:10px;box-shadow:0 5px 0 #e4dac7,0 10px 22px #415b6e1a}.game-stage{border-radius:5px;aspect-ratio:4/3}.hud{inset:9px 10px auto;gap:12px}.hud-label{font-size:7px}.hud-stat strong{font-size:9px}.coins-stat{margin-top:8px;gap:3px}.coins-stat strong{font-size:8px}.coin-icon{font-size:13px}.lives-stat strong{font-size:12px}.overlay-card{margin-top:15px;padding:15px 10px 11px;min-width:80%;border-radius:8px}.mini-kicker{font-size:7px}.overlay-card h1{font-size:17px;margin:7px 0 4px}.overlay-card h1 span{font-size:10px}.overlay-card h1 em{font-size:11px}.overlay-copy{font-size:10px;margin:5px 0 10px}.play-button{padding:9px 13px;font-size:10px}.control-hint{font-size:7px;margin-top:10px}.control-hint kbd{font-size:7px;padding:2px 3px}.game-footer{height:35px;padding:0 2px}.footer-tip{font-size:9px;gap:5px}.footer-tip b{font-size:7px}.tip-icon{font-size:14px}.footer-controls{display:none}.touch-controls{display:flex;align-items:center;justify-content:space-between;padding:15px 5px 0}.touch-arrows{display:flex;gap:10px}.touch-controls button{height:54px;min-width:65px;border:1px solid #ddd3c1;background:#fffaf0;border-radius:11px;box-shadow:0 4px 0 #ddd3c1;color:#53738a;font-size:19px;touch-action:none;user-select:none}.touch-controls button:active,.touch-controls button.pressed{background:#ffcf55;transform:translateY(2px);box-shadow:0 2px 0 #d1aa4f}.touch-controls .touch-jump{width:100px;background:#f05443;border-color:#dc4a3b;box-shadow:0 4px 0 #bd4035;color:white;font-size:10px;font-weight:900;letter-spacing:1px}.touch-jump span{font-size:17px;margin-left:4px}.page-foot{font-size:7px;margin:18px 4px 0;letter-spacing:.6px}}
@media(max-width:390px){.top-note{display:none}.overlay-card{min-width:88%}.footer-tip{font-size:8px}.hud{gap:8px}.hud-stat{min-width:48px}}

